<?php
require_once __DIR__.'/includes/db.php';require_once __DIR__.'/includes/config.php';require_login();
$local=(int)($_SESSION['pending_payment_order']??0);$rp=(string)($_SESSION['pending_payment_rp_order']??'');$no=(string)($_SESSION['pending_payment_order_no']??'');$amount=(int)($_SESSION['pending_payment_amount']??0);
if(!$local||!$rp||!$no||!$amount){header('Location: cart.php');exit;}
$s=$pdo->prepare("SELECT total,payment_status FROM orders WHERE id=? AND user_id=? AND razorpay_order_id=?");$s->execute([$local,$_SESSION['user_id'],$rp]);$order=$s->fetch();
if(!$order||$order['payment_status']==='Paid'){header('Location: track.php?order='.urlencode($no));exit;}
?><!doctype html><html lang="gu"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GoldCart Test Payment</title><link rel="stylesheet" href="assets/style.css"></head><body><header class="topbar"><a class="brand" href="index.php">GOLD<span>CART</span></a></header><main class="form-wrap"><div class="panel"><p class="eyebrow">RAZORPAY TEST MODE</p><h1>Payment</h1><p>Order: <?=htmlspecialchars($no)?></p><h2>₹<?=number_format((float)$order['total'],2)?></h2><p class="muted">Test Mode: વાસ્તવિક પૈસા કપાતા નથી.</p><button class="btn" id="payBtn">Pay Securely</button><p id="msg" class="muted"></p><form id="verify" method="post" action="payment_verify.php" hidden><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf_token())?>"><input name="razorpay_payment_id" id="pid"><input name="razorpay_order_id" id="oid"><input name="razorpay_signature" id="sig"></form><form id="fail" method="post" action="payment_failed.php" hidden><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf_token())?>"></form></div></main><script src="https://checkout.razorpay.com/v1/checkout.js"></script><script>
document.getElementById('payBtn').onclick=function(){this.disabled=true;document.getElementById('msg').textContent='Checkout ખૂલી રહ્યું છે...';const r=new Razorpay({key:<?=json_encode(RAZORPAY_KEY_ID)?>,amount:<?=$amount?>,currency:'INR',name:'GoldCart',description:'Order <?=htmlspecialchars($no,ENT_QUOTES)?>',order_id:<?=json_encode($rp)?>,theme:{color:'#D4AF37'},handler:function(x){document.getElementById('pid').value=x.razorpay_payment_id;document.getElementById('oid').value=x.razorpay_order_id;document.getElementById('sig').value=x.razorpay_signature;document.getElementById('verify').submit();},modal:{ondismiss:function(){document.getElementById('payBtn').disabled=false;document.getElementById('msg').textContent='Payment window બંધ થયું. ફરી પ્રયાસ કરી શકો છો.';}}});r.on('payment.failed',function(){document.getElementById('fail').submit();});r.open();};
</script></body></html>
